pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(address actor, bytes32 hash) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        // Rule: right after locking in a guess, the target block is not yet
        // reached, so settle() must revert for every actor/hash.
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "settle must revert before the target block");
    }
}

