pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 n) public {
        vm.assume(actor != address(0) && actor != address(c));
        n = bound(n, 1, 1_000_000_000);

        // Roll past block n so its hash becomes known history.
        vm.roll(n + 1);
        bytes32 ans = blockhash(n);

        // Lock in the true answer hash at block n-1 so the target is block n.
        vm.roll(n - 1);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(ans);

        // Contract now holds 1 ether seed + 1 ether stake.
        require(address(c).balance == 2 ether, "stake not held");

        // Settle at a block strictly greater than the target.
        vm.roll(n + 2);
        vm.prank(actor);
        (bool ok, ) = address(c).call("");
        assertTrue(ok, "settle reverted");

        // A correct guess must always pay out the 2-ether prize.
        assertTrue(address(c).balance == 0);
    }
}

