pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 k) public {
        // admissible domain: a plain EOA caller distinct from the contract
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.code.length == 0);

        // pick a target block n; read its (deterministic) hash while it is in the past,
        // then rewind so lockInGuess targets exactly that block
        uint256 n = bound(k, 2, 1_000_000);
        vm.roll(n);
        bytes32 h = blockhash(n - 1);
        vm.assume(h != bytes32(0));

        vm.roll(n - 2); // current block = n-2, so lockInGuess target = n-1
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h); // guess == blockhash(target) == h (nonzero)

        vm.roll(n); // block.number = n > target = n-1
        vm.prank(actor);
        c.settle(); // answer = blockhash(n-1) = h != 0, guess == h -> payout

        // reference: the correct guess wins, so the 2-ether prize was paid out;
        // the mutant (guess forced to bytes32(0)) never wins and keeps its 2 ether.
        assertTrue(address(c).balance == 0);
    }
}

