pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint128 targetBlock, address actor) public {
        uint256 T = bound(uint256(targetBlock), 300, type(uint128).max - 2);
        vm.assume(actor != address(0) && actor != address(c));

        // Peek the value that blockhash(T) will return once block T is in the past.
        vm.roll(T + 1);
        bytes32 answer = blockhash(T);
        vm.assume(answer != bytes32(0));

        // Lock in at block T-1 so the guess target is exactly block T.
        vm.roll(T - 1);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(answer);

        // Settle at a later block; blockhash(T) equals the locked answer.
        vm.roll(T + 1);
        vm.prank(actor);
        c.settle();

        // General rule: a correct guess of the target block's hash always pays out the
        // full 2 ether, draining the contract to zero balance.
        assertTrue(address(c).balance == 0, "correct blockhash guess must win the prize");
    }
}

