pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint128 t, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(t > 300);

        // compute the blockhash of the settle-target block (must be a past block to be nonzero)
        vm.roll(uint256(t) + 2);
        bytes32 h = blockhash(uint256(t) + 1);
        vm.assume(h != bytes32(0));

        // lock in the guess at block t+1, so the settle target is block t+1
        vm.roll(uint256(t) + 1);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // settle after the target block: answer == blockhash(t+1) == h, so the player wins
        vm.roll(uint256(t) + 2);
        vm.prank(actor);
        c.settle();

        // reference: the correct guess wins the prize, so c's balance is drained to 0
        assertTrue(address(c).balance == 0);
    }
}

