pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(0));
        vm.assume(h != bytes32(0));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // General rule: after lockInGuess(h), the contract stores exactly h
        // as the caller's guess. The mutant drops the store, leaving bytes32(0).
        assertTrue(c.guesses(actor).guess == h);
    }
}
